using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class JournalEntryRepository(NamaaDbContext db):IJournalEntryRepository{public Task<bool>ExistsByNumberAsync(string number,CancellationToken cancellationToken=default)=>db.JournalEntries.AsNoTracking().AnyAsync(x=>x.EntryNumber==number,cancellationToken);public Task<JournalEntry?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.JournalEntries.AsNoTracking().Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,cancellationToken);public Task<JournalEntry?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.JournalEntries.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,cancellationToken);public async Task<IReadOnlyList<JournalEntry>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.JournalEntries.AsNoTracking().Include(x=>x.Lines).OrderByDescending(x=>x.EntryDate).ToListAsync(cancellationToken);public async Task AddAsync(JournalEntry entity,CancellationToken cancellationToken=default)=>await db.JournalEntries.AddAsync(entity,cancellationToken);}
